use verus::*;

verus! {

    /// A predicate stating that the elements of slice `a` are in nondecreasing order.
    spec fn slice_sorted(a: &[int]) -> bool {
        // For all indices i and j with i ≤ j < a.len(), we have a[i] ≤ a[j].
        forall |i: usize, j: usize| i <= j && j < a.len() ==> a[i] <= a[j]
    }

    /// Binary search specification.
    ///
    /// Given a nondecreasing slice `a` of mathematical integers and
    /// a target integer `k`, the function returns `true` if and only if
    /// there exists some index `i` within the bounds of `a` such that
    /// `a[i] == k`.
    ///
    /// This handles empty slices and slices with duplicate values.
    spec fn bin_search(a: &[int], k: int) -> bool
        requires
            // The input slice must be sorted in nondecreasing order.
            slice_sorted(a)
        ensures
            // The result is true exactly when k appears somewhere in a.
            result <==> (exists |i: usize| i < a.len() && a[i] == k)
    ;
}